mapper.select:
SELECT a.id, a.version, a.rule_key, a.reference_key, b.name AS reference_name, c.id AS feature_id, c.feature_key, COALESCE(c.custom_name, c.default_name) AS feature_name, d.id AS app_id, d.name AS app_name, e.id AS domain_id, e.name AS domain_name, a.name, a.pattern, a.scope_type, a.reset_period, a.start_value, a.enabled, a.system_preset, (b.default_rule_key = a.rule_key) AS default_rule, a.description, ((SELECT count(*) FROM t_sys_number_reference usage_ref WHERE usage_ref.default_rule_key = a.rule_key) + (SELECT count(*) FROM t_sys_basic_data_category usage_category WHERE usage_category.number_rule_key = a.rule_key AND usage_category.number_mode != 'MANUAL')) AS usage_count FROM t_sys_number_rule a INNER JOIN t_sys_number_reference b ON b.reference_key = a.reference_key INNER JOIN t_sys_feature c ON c.id = b.feature_id INNER JOIN t_sys_app d ON d.id = c.app_id INNER JOIN t_sys_domain e ON e.id = d.domain_id
a.scope_type = #{form.scopeType}
AND e.id = #{form.domainId} AND d.id = #{form.appId} AND c.id = #{form.featureId}
AND a.reference_key = #{form.referenceKey}
AND a.enabled = #{form.enabled}
AND (a.rule_key LIKE CONCAT('%', #{form.keyword}, '%') OR a.name LIKE CONCAT('%', #{form.keyword}, '%'))
ORDER BY ${listQuery.sortColumn} ${listQuery.sortOrder}, a.id ORDER BY e.seq, d.seq, COALESCE(c.custom_seq, c.default_seq), a.system_preset DESC, a.rule_key, a.id

SELECT a.current_value
FROM t_sys_number_counter a
WHERE a.rule_key = #{ruleKey}
  AND a.scope_key = #{scopeKey}
  AND a.period_key = #{periodKey}
